// N-QUEENS (#51) — O(n!) time, O(n) space
function solveNQueens(n) {
    const result = [];
    const cols  = new Set(); // occupied columns
    const diag1 = new Set(); // occupied '\\' diagonals (row - col)
    const diag2 = new Set(); // occupied '/' diagonals  (row + col)
    const queens = new Array(n); // queens[row] = col of queen in that row

    function backtrack(row) {
        if (row === n) {
            // Construct board from queens array
            result.push(queens.map(c =>
                '.'.repeat(c) + 'Q' + '.'.repeat(n - c - 1)
            ));
            return;
        }
        for (let col = 0; col < n; col++) {
            if (cols.has(col) || diag1.has(row - col) || diag2.has(row + col))
                continue; // conflict: skip this column

            // CHOOSE
            cols.add(col); diag1.add(row - col); diag2.add(row + col);
            queens[row] = col;

            // EXPLORE
            backtrack(row + 1);

            // UNCHOOSE
            cols.delete(col); diag1.delete(row - col); diag2.delete(row + col);
        }
    }
    backtrack(0);
    return result;
}

