// SUDOKU SOLVER (#37) — backtracking O(9^81) worst, O(1) with pruning
function solveSudoku(board) {
    // Initialise constraint sets from pre-filled cells
    const rows  = Array.from({length: 9}, () => new Set());
    const cols  = Array.from({length: 9}, () => new Set());
    const boxes = Array.from({length: 9}, () => new Set());

    for (let r = 0; r < 9; r++) {
        for (let c = 0; c < 9; c++) {
            if (board[r][c] !== '.') {
                const d = board[r][c];
                const box = Math.floor(r/3)*3 + Math.floor(c/3);
                rows[r].add(d); cols[c].add(d); boxes[box].add(d);
            }
        }
    }

    function backtrack() {
        // Find first empty cell
        for (let r = 0; r < 9; r++) {
            for (let c = 0; c < 9; c++) {
                if (board[r][c] !== '.') continue;
                const box = Math.floor(r/3)*3 + Math.floor(c/3);

                for (let d = 1; d <= 9; d++) {
                    const digit = String(d);
                    if (rows[r].has(digit) || cols[c].has(digit) ||
                        boxes[box].has(digit)) continue; // conflict: skip

                    // PLACE digit
                    board[r][c] = digit;
                    rows[r].add(digit); cols[c].add(digit); boxes[box].add(digit);

                    if (backtrack()) return true; // solution found: propagate up

                    // REMOVE digit (backtrack)
                    board[r][c] = '.';
                    rows[r].delete(digit); cols[c].delete(digit); boxes[box].delete(digit);
                }
                return false; // no digit worked: backtrack
            }
        }
        return true; // no empty cells: board is solved
    }
    backtrack();
}

// KEY DESIGN DECISIONS:
// 1. Return true/false: propagates success upward immediately
// 2. Return false when no digit fits: triggers backtrack to caller
// 3. Return true when no empty cell found: base case = solution complete
// 4. Box formula: Math.floor(r/3)*3 + Math.floor(c/3) gives 0-8
//    (0,0)-(2,2)->0, (0,3)-(2,5)->1, ..., (6,6)-(8,8)->8

// OPTIMISATION: choose the cell with fewest valid digits (MRV heuristic)
// Instead of first empty cell, find the empty cell with minimum options
// This dramatically reduces the search tree in practice
// Standard interviews don't require this but it's worth mentioning

