function solveSudokuImpl(board) {
  const rows = Array.from({length:9},()=>new Set());
  const cols = Array.from({length:9},()=>new Set());
  const boxes = Array.from({length:9},()=>new Set());
  for (let r=0;r<9;r++) for (let c=0;c<9;c++) {
    if (board[r][c]!=='.') {
      const d=board[r][c], box=boxIndex(r,c);
      rows[r].add(d); cols[c].add(d); boxes[box].add(d);
    }
  }
  function backtrack() {
    for (let r=0;r<9;r++) for (let c=0;c<9;c++) {
      if (board[r][c]!=='.') continue;
      const box=boxIndex(r,c);
      for (let d=1;d<=9;d++) {
        const digit=String(d);
        if (rows[r].has(digit)||cols[c].has(digit)||boxes[box].has(digit)) continue;
        board[r][c]=digit; rows[r].add(digit); cols[c].add(digit); boxes[box].add(digit);
        if (backtrack()) return true;
        board[r][c]='.'; rows[r].delete(digit); cols[c].delete(digit); boxes[box].delete(digit);
      }
      return false;
    }
    return true;
  }
  backtrack();
}

