// WORD SEARCH I (#79) — O(m*n*4^L) time, O(L) space
function exist(board, word) {
    const m = board.length, n = board[0].length;
    const DIRS = [[0,1],[0,-1],[1,0],[-1,0]];

    function dfs(r, c, idx) {
        if (idx === word.length) return true; // all chars matched
        if (r < 0 || r >= m || c < 0 || c >= n) return false;
        if (board[r][c] !== word[idx]) return false; // char mismatch

        const temp = board[r][c];
        board[r][c] = '#'; // mark visited in-place

        for (const [dr, dc] of DIRS) {
            if (dfs(r+dr, c+dc, idx+1)) {
                board[r][c] = temp; // restore before returning true
                return true;
            }
        }
        board[r][c] = temp; // restore on failure
        return false;
    }

    for (let r = 0; r < m; r++)
        for (let c = 0; c < n; c++)
            if (dfs(r, c, 0)) return true;
    return false;
}

