// WORD SEARCH II (#212) — Trie + backtracking O(m*n*4^L) amortised
// (Same as Module 8 Lesson 9, shown here for context)
function findWords(board, words) {
    // Build Trie
    const root = {};
    for (const word of words) {
        let node = root;
        for (const c of word) {
            if (!node[c]) node[c] = {};
            node = node[c];
        }
        node['$'] = word; // store word at end marker
    }

    const m = board.length, n = board[0].length;
    const result = [];
    const DIRS = [[0,1],[0,-1],[1,0],[-1,0]];

    function dfs(r, c, node) {
        const char = board[r][c];
        if (!node[char]) return; // no word with this prefix: prune
        const next = node[char];
        if (next['$']) {
            result.push(next['$']); // found a word
            delete next['$'];       // remove to avoid duplicates
        }
        board[r][c] = '#'; // mark visited
        for (const [dr,dc] of DIRS) {
            const nr=r+dr, nc=c+dc;
            if (nr>=0&&nr<m&&nc>=0&&nc<n&&board[nr][nc]!=='#')
                dfs(nr, nc, next);
        }
        board[r][c] = char; // restore
        // Prune: remove empty Trie nodes to reduce future work
        if (Object.keys(next).length === 0) delete node[char];
    }

    for (let r=0;r<m;r++)
        for (let c=0;c<n;c++)
            dfs(r, c, root);
    return result;
}

