// EXPRESSION ADD OPERATORS (#282)
// O(4^n * n) time, O(n) space (call stack + expression string)
function addOperators(num, target) {
    const result = [];

    // path: expression string built so far
    // total: current computed value of expression
    // last: the last operand (for undoing when * appears)
    function backtrack(index, path, total, last) {
        if (index === num.length) {
            if (total === target) result.push(path);
            return;
        }

        for (let end = index + 1; end <= num.length; end++) {
            const str = num.slice(index, end);
            // LEADING ZERO CHECK: '05' is invalid (only '0' itself is ok)
            if (str.length > 1 && str[0] === '0') break;

            const curr = Number(str);

            if (index === 0) {
                // First number: no operator, just set up state
                backtrack(end, str, curr, curr);
            } else {
                // ADDITION: total + curr
                backtrack(end, path + '+' + str, total + curr, curr);

                // SUBTRACTION: total - curr (last is -curr for future * handling)
                backtrack(end, path + '-' + str, total - curr, -curr);

                // MULTIPLICATION: undo last, add last*curr
                // total - last + last*curr
                backtrack(end, path + '*' + str, total - last + last * curr, last * curr);
            }
        }
    }
    backtrack(0, '', 0, 0);
    return result;
}

