// REMOVE INVALID PARENTHESES (#301) — BFS: O(n * 2^n)
function removeInvalidParentheses(s) {
    function isValid(str) {
        let open = 0;
        for (const c of str) {
            if (c === '(') open++;
            else if (c === ')') {
                open--;
                if (open < 0) return false; // close before open: invalid
            }
        }
        return open === 0; // must have equal opens and closes
    }

    if (isValid(s)) return [s]; // already valid

    const result = [];
    const visited = new Set([s]);
    let queue = [s];
    let found = false;

    while (queue.length && !found) {
        const next = [];
        for (const curr of queue) {
            for (let i = 0; i < curr.length; i++) {
                // Only try removing '(' or ')' (not letters)
                if (curr[i] !== '(' && curr[i] !== ')') continue;
                const candidate = curr.slice(0, i) + curr.slice(i + 1);
                if (visited.has(candidate)) continue;
                visited.add(candidate);
                if (isValid(candidate)) {
                    result.push(candidate);
                    found = true; // mark: stop expanding at next level
                } else if (!found) {
                    next.push(candidate); // only expand if no valid found yet
                }
            }
        }
        queue = next;
    }
    return result;
}

