// DFS ALTERNATIVE with explicit min-removal counting:
function removeInvalidParentheses_dfs(s) {
    // Count minimum removals needed: scan and count mismatched parens
    let minRemove = 0, open = 0;
    for (const c of s) {
        if (c === '(') open++;
        else if (c === ')') {
            if (open > 0) open--;
            else minRemove++; // unmatched ')'
        }
    }
    minRemove += open; // remaining unmatched '('

    const result = new Set();
    function dfs(idx, currOpen, currClose, removals, path) {
        if (removals > minRemove) return; // exceeded min removals: prune
        if (idx === s.length) {
            if (currOpen === currClose) result.add(path);
            return;
        }
        const c = s[idx];
        // Option 1: skip this character (remove it)
        if (c === '(' || c === ')') dfs(idx+1, currOpen, currClose, removals+1, path);
        // Option 2: keep this character
        if (c === '(') dfs(idx+1, currOpen+1, currClose, removals, path+c);
        else if (c === ')' && currClose < currOpen)
            dfs(idx+1, currOpen, currClose+1, removals, path+c);
        else if (c !== '(' && c !== ')') dfs(idx+1, currOpen, currClose, removals, path+c);
    }
    dfs(0, 0, 0, 0, '');
    return [...result];
}

